$R=__DIR__.'/..'; require "$R/lib/Db.php"; require "$R/lib/Jwt.php"; require "$R/lib/LineImageCompressor.php"; $C=require "$R/config.php";
date_default_timezone_set('Asia/Tehran');
function sw3_json($x,$s=200){http_response_code($s);echo json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function sw3_err($m,$s=400){sw3_json(['error'=>$m],$s);}
function sw3_user(){global $C;$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/Bearer\s+(.+)/i',$h,$m))sw3_err('توکن نامعتبر است',401);$p=Jwt::verify(trim($m[1]),$C['jwt_secret']);if(!$p)sw3_err('توکن منقضی یا نامعتبر است',401);$u=Db::one("SELECT u.id,u.role_id,u.is_active,r.title role_title,r.is_admin FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=?",[$p['sub']]);if(!$u||!$u['is_active'])sw3_err('کاربر نامعتبر است',401);return $u;}
function sw3_admin($u){return !empty($u['is_admin'])||in_array($u['role_title']??'', ['مدیر کل','رییس اداره بازرسی','نیروی اداری ارشد'],true);}
function sw3_ids($u){if(sw3_admin($u))return null;$r=Db::all('SELECT line_id FROM user_lines WHERE user_id=?',[$u['id']]);return array_map('intval',array_column($r,'line_id'));}
function sw3_allowed($u){if(sw3_admin($u))return true;$row=Db::one("SELECT value FROM app_settings WHERE `key`='role_app_items'");$cfg=$row?json_decode($row['value'],true):[];$rid=(string)$u['role_id'];if(!is_array($cfg)||!array_key_exists($rid,$cfg))return true;$v=$cfg[$rid];return is_array($v)&&(in_array('LineLocation',$v,true)||in_array('StationCapture',$v,true)||in_array('LineStationCapture',$v,true));}
function sw3_col($table,$col,$def){$q=Db::one("SELECT COUNT(*) c FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND COLUMN_NAME=?",[$table,$col]);if(!(int)($q['c']??0))Db::run("ALTER TABLE `$table` ADD COLUMN `$col` $def");}
function sw3_schema(){Db::run("CREATE TABLE IF NOT EXISTS line_station_locations (id BIGINT AUTO_INCREMENT PRIMARY KEY,line_id INT NOT NULL,station_code VARCHAR(80) NULL,station_status VARCHAR(30) NOT NULL DEFAULT 'registered',station_name VARCHAR(190) NULL,latitude DECIMAL(10,7) NOT NULL,longitude DECIMAL(10,7) NOT NULL,accuracy_m DECIMAL(10,2) NULL,physical_address TEXT NULL,street VARCHAR(190) NULL,location_photo_path VARCHAR(500) NULL,captured_by INT NOT NULL,captured_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_lsl_line(line_id),INDEX idx_lsl_captured(captured_by,captured_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");foreach([['station_code','VARCHAR(80) NULL'],['station_status',"VARCHAR(30) NOT NULL DEFAULT 'registered'"],['physical_address','TEXT NULL'],['street','VARCHAR(190) NULL'],['updated_at','DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP']] as $x)sw3_col('line_station_locations',$x[0],$x[1]);Db::run("CREATE TABLE IF NOT EXISTS line_station_signs (id BIGINT AUTO_INCREMENT PRIMARY KEY,station_location_id BIGINT NOT NULL,sign_type_id INT NOT NULL,photo_path VARCHAR(500) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_lss_station(station_location_id),INDEX idx_lss_type(sign_type_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");}
function sw3_dist($a,$b,$c,$d){$p=M_PI/180;$x=sin(($c-$a)*$p/2)**2+cos($a*$p)*cos($c*$p)*sin(($d-$b)*$p/2)**2;return 6371000*2*asin(min(1,sqrt($x)));}
function sw3_fa($n){return strtr((string)$n,'0123456789','۰۱۲۳۴۵۶۷۸۹');}
function sw3_jalali($gy,$gm,$gd){$gdm=[0,31,28,31,30,31,30,31,31,30,31,30,31];$gy2=$gm>2?$gy+1:$gy;$days=355666+(365*$gy)+intdiv($gy2+3,4)-intdiv($gy2+99,100)+intdiv($gy2+399,400)+$gd;for($i=1;$i<$gm;$i++)$days+=$gdm[$i];$jy=-1595+33*intdiv($days-79,12053);$days%=12053;$jy+=4*intdiv($days,1461);$days%=1461;if($days>365){$jy+=intdiv($days-1,365);$days=($days-1)%365;}$jm=$days<186?1+intdiv($days,31):7+intdiv($days-186,30);$jd=1+($days<186?$days%31:($days-186)%30);return sprintf('%04d/%02d/%02d',$jy,$jm,$jd);}
function sw3_fadt($dt){$t=strtotime($dt);if(!$t)return null;$g=getdate($t);return sw3_fa(sw3_jalali($g['year'],$g['mon'],$g['mday'])).' '.sw3_fa(date('H:i',$t));}
function sw3_img($v,$prefix){if(!$v)return null;if(strpos($v,'base64,')!==false)$v=base64_decode(substr($v,strpos($v,',')+1),true);if(!$v||strlen($v)>8*1024*1024||@getimagesizefromstring($v)===false)sw3_err('تصویر نامعتبر یا بزرگ‌تر از ۸ مگابایت است');$rel='/uploads/line-locations/'.date('Y/m').'/';$dir=__DIR__.$rel;if(!is_dir($dir)&&!@mkdir($dir,0775,true))sw3_err('امکان ایجاد پوشه تصاویر وجود ندارد',500);$f=$dir.$prefix.'_'.bin2hex(random_bytes(8)).'.jpg';if(!LineImageCompressor::fromBinary($v,$f))sw3_err('ذخیره تصویر ناموفق بود',500);return $rel.basename($f);}
function sw3_url($p){if(!$p)return null;if(preg_match('#^https?://#i',$p))return $p;return 'https://app.yousefipour.ir/'.ltrim($p,'/');}
$u=sw3_user();if(!sw3_allowed($u))sw3_err('این قابلیت برای سمت شما فعال نیست',403);sw3_schema();$op=$_GET['op']??$_POST['op']??'permission';
if($op==='permission')sw3_json(['allowed'=>true,'can_manage'=>sw3_admin($u),'max_accuracy_m'=>20]);
