if($op==='lines'){$ids=sw3_ids($u);$lat=isset($_GET['lat'])?(float)$_GET['lat']:null;$lng=isset($_GET['lng'])?(float)$_GET['lng']:null;$where='';$a=[];if(is_array($ids)){if(!$ids)sw3_json([]);$where=' WHERE l.id IN('.implode(',',array_fill(0,count($ids),'?')).')';$a=$ids;}$rows=Db::all("SELECT l.id,l.code,l.origin,l.destination,l.status,l.latitude,l.longitude FROM `lines` l$where ORDER BY l.code",$a);foreach($rows as &$r){$r['distance_m']=null;if($lat!==null&&$lng!==null&&is_numeric($r['latitude'])&&is_numeric($r['longitude']))$r['distance_m']=round(sw3_dist($lat,$lng,$r['latitude'],$r['longitude']),1);}unset($r);usort($rows,function($a,$b){if($a['distance_m']===null)return 1;if($b['distance_m']===null)return -1;return $a['distance_m']<=>$b['distance_m'];});sw3_json(['nearest'=>array_slice($rows,0,5),'all'=>$rows]);}
if($op==='mine'){$r=Db::all("SELECT s.id,s.line_id,s.station_status,s.latitude,s.longitude,s.accuracy_m,s.physical_address,s.location_photo_path,s.captured_at,s.updated_at,l.code line_code,l.origin,l.destination,CONCAT(COALESCE(u.first_name,''),' ',COALESCE(u.last_name,'')) captured_by,(SELECT COUNT(*) FROM line_station_signs z WHERE z.station_location_id=s.id) sign_count FROM line_station_locations s JOIN `lines` l ON l.id=s.line_id LEFT JOIN users u ON u.id=s.captured_by WHERE s.captured_by=? ORDER BY s.updated_at DESC,s.id DESC",[$u['id']]);foreach($r as &$x){$x['location_photo_url']=sw3_url($x['location_photo_path']);$x['captured_at_fa']=sw3_fadt($x['captured_at']);}unset($x);sw3_json($r);}
if($op==='detail'){$id=(int)($_GET['id']??0);$s=Db::one('SELECT s.*,l.code line_code,l.origin,l.destination,l.status line_status FROM line_station_locations s JOIN `lines` l ON l.id=s.line_id WHERE s.id=?',[$id]);if(!$s)sw3_err('ایستگاه یافت نشد',404);if((int)$s['captured_by']!==(int)$u['id']&&!sw3_admin($u))sw3_err('دسترسی ندارید',403);$s['location_photo_url']=sw3_url($s['location_photo_path']);$s['captured_at_fa']=sw3_fadt($s['captured_at']);$s['signs']=Db::all('SELECT z.id,z.sign_type_id,t.title,z.photo_path FROM line_station_signs z JOIN station_sign_types t ON t.id=z.sign_type_id WHERE z.station_location_id=? ORDER BY z.id',[$id]);foreach($s['signs'] as &$z)$z['photo_url']=sw3_url($z['photo_path']);unset($z);sw3_json($s);}
if($op==='save'){$b=json_decode(file_get_contents('php://input'),true)?:[];$id=(int)($b['station_id']??0);$method=($b['location_method']??'gps')==='manual'?'manual':'gps';$lat=$b['latitude']??null;$lng=$b['longitude']??null;$acc=$b['accuracy_m']??null;if(!is_numeric($lat)||!is_numeric($lng)||$lat<-90||$lat>90||$lng<-180||$lng>180)sw3_err('مختصات نامعتبر است');if($method==='gps'&&(!is_numeric($acc)||$acc<0||$acc>20))sw3_err('دقت GPS باید حداکثر ۲۰ متر باشد',422);if($method==='manual')$acc=null;$status=($b['station_status']??'registered')==='missing'?'missing':'registered';$lid=(int)($b['line_id']??0);$missing=trim((string)($b['missing_line_title']??''));if($status==='missing'&&!$missing)sw3_err('عنوان خطی که در فهرست نیست الزامی است');if($status==='registered'&&!$lid)sw3_err('خط انتخاب نشده است');$ids=sw3_ids($u);if($lid&&is_array($ids)&&!in_array($lid,$ids,true))sw3_err('این خط در محدوده دسترسی شما نیست',403);if($status==='missing'){$lid=0;if(!sw3_admin($u))sw3_err('ثبت خط خارج از فهرست فقط برای مدیر مجاز است',403);Db::run("INSERT INTO `lines`(code,origin,destination,status) VALUES(NULL,?,?,?)",[$missing,$missing,'inactive']);$lid=(int)Db::lastId();}$address=trim((string)($b['physical_address']??''));if($address==='')sw3_err('آدرس محل ایستگاه الزامی است');$signs=$b['signs']??[];if(!is_array($signs)||!count($signs))sw3_err('حداقل یک تابلو الزامی است');$lp=sw3_img($b['location_photo']??null,'station-location');$now=date('Y-m-d H:i:s');$old=$id?Db::one('SELECT * FROM line_station_locations WHERE id=?',[$id]):null;if($old){if((int)$old['captured_by']!==(int)$u['id']&&!sw3_admin($u))sw3_err('فقط ثبت‌کننده می‌تواند ایستگاه را ویرایش کند',403);if(!$lp)$lp=$old['location_photo_path'];$lid=(int)$old['line_id'];Db::run('UPDATE line_station_locations SET line_id=?,station_code=NULL,station_status=?,station_name=NULL,latitude=?,longitude=?,accuracy_m=?,physical_address=?,street=NULL,location_photo_path=?,updated_at=? WHERE id=?',[$lid,$status,$lat,$lng,$acc,$address,$lp,$now,$id]);$sid=$id;Db::run('DELETE FROM line_station_signs WHERE station_location_id=?',[$sid]);}else{Db::run('INSERT INTO line_station_locations(line_id,station_code,station_status,station_name,latitude,longitude,accuracy_m,physical_address,street,location_photo_path,captured_by,captured_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',[$lid,null,$status,null,$lat,$lng,$acc,$address,null,$lp,$u['id'],$now,$now]);$sid=(int)Db::lastId();}foreach($signs as $sg){$tid=(int)($sg['type_id']??0);if(!Db::one('SELECT id FROM station_sign_types WHERE id=? AND is_active=1',[$tid]))sw3_err('نوع تابلو نامعتبر است');$p=sw3_img($sg['photo']??null,'station-sign');if(!$p&&isset($sg['photo_path']))$p=trim((string)$sg['photo_path']);if(!$p)sw3_err('تصویر هر تابلو الزامی است');Db::run('INSERT INTO line_station_signs(station_location_id,sign_type_id,photo_path) VALUES(?,?,?)',[$sid,$tid,$p]);}Db::run('UPDATE `lines` SET latitude=?,longitude=?,location_accuracy_m=?,station_name=NULL,location_updated_by=?,location_updated_at=?,station_location_id=?,station_physical_address=?,station_street=NULL WHERE id=?',[$lat,$lng,$acc,$u['id'],$now,$sid,$address,$lid]);sw3_json(['ok'=>true,'id'=>$sid,'line_id'=>$lid,'station_status'=>$status,'latitude'=>(float)$lat,'longitude'=>(float)$lng,'accuracy_m'=>$acc,'physical_address'=>$address,'captured_at'=>$now,'captured_at_fa'=>sw3_fadt($now),'location_photo_url'=>sw3_url($lp)]);}
